<?php
namespace App\Filament\Resources;
use App\Models\EmailDeliveryLog; use App\Services\TransactionalMailService; use Filament\Actions\Action; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table;
class EmailDeliveryLogResource extends AdminResource { protected static ?string $model=EmailDeliveryLog::class; protected static string|null|\BackedEnum $navigationIcon='heroicon-o-clock'; protected static string|\UnitEnum|null $navigationGroup='Emails'; protected static ?string $navigationLabel='Historique'; protected static ?int $navigationSort=3; public static function canCreate():bool{return false;} public static function canEdit(\Illuminate\Database\Eloquent\Model $r):bool{return false;} public static function table(Table $t):Table{return $t->columns([TextColumn::make('created_at')->label('Date')->dateTime('d/m/Y H:i')->sortable(),TextColumn::make('template_key')->label('Template')->searchable(),TextColumn::make('recipient')->label('Destinataire')->searchable(),TextColumn::make('status')->badge(),TextColumn::make('attempts')->label('Tentatives')->numeric(),TextColumn::make('last_attempt_at')->label('Dernier essai')->dateTime('d/m/Y H:i'),TextColumn::make('error_message')->label('Erreur')->limit(100)])->filters([SelectFilter::make('status')->options(['queued'=>'En file','sent'=>'Envoyé','failed'=>'Échec'])])->recordActions([Action::make('retry')->label('Réessayer')->visible(fn(EmailDeliveryLog $r)=>$r->status==='failed')->requiresConfirmation()->action(function(EmailDeliveryLog $r){$r->update(['status'=>'queued','error_message'=>null]);app(TransactionalMailService::class)->queue($r->template_key,$r->recipient);})])->defaultSort('created_at','desc');} public static function getPages():array{return ['index'=>EmailDeliveryLogResource\Pages\ListEmailDeliveryLogs::route('/')];} }
